<?php
require "auth.php"; $pageTitle="Expenses"; $active="expenses";
if(isset($_POST['save'])){$n=trim($_POST['expense_name']);$a=(float)$_POST['amount'];$d=$_POST['expense_date'];$desc=trim($_POST['description']);$s=$conn->prepare("INSERT INTO expenses(expense_name,amount,expense_date,description,created_by) VALUES(?,?,?,?,?)");$s->bind_param("sdssi",$n,$a,$d,$desc,$_SESSION['user_id']);$s->execute();header("Location: expenses.php");exit;}
if(isset($_GET['delete'])){$conn->query("DELETE FROM expenses WHERE id=".(int)$_GET['delete']);header("Location: expenses.php");exit;}
require "partials/header.php"; ?>
<div class="panel"><h3>Add Expense</h3><form method="post"><div class="form-grid"><div class="field"><label>Expense Name</label><input name="expense_name" required></div><div class="field"><label>Amount (TZS)</label><input type="number" step="0.01" min="0" name="amount" required></div><div class="field"><label>Date</label><input type="date" name="expense_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Description</label><textarea name="description"></textarea></div></div><div class="form-actions"><button class="btn primary" name="save">Save Expense</button></div></form></div>
<div class="panel" style="margin-top:20px"><h3>Expense History</h3><table class="table"><tr><th>Date</th><th>Expense</th><th>Description</th><th>Amount</th><th></th></tr><?php $rs=$conn->query("SELECT * FROM expenses ORDER BY expense_date DESC,id DESC");while($r=$rs->fetch_assoc()):?><tr><td><?=e($r['expense_date'])?></td><td><?=e($r['expense_name'])?></td><td><?=e($r['description'])?></td><td>TZS <?=money($r['amount'])?></td><td><a class="btn btn-sm danger-btn" data-confirm="Delete expense?" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endwhile;?></table></div>
